import { db } from '../firebase/config';
import {
  collection,
  setDoc,
  getDocs,
  deleteDoc,
  doc,
  query,
  where,
  serverTimestamp,
  onSnapshot,
  runTransaction,
} from 'firebase/firestore';
// Aliased so it can't be confused with the browser's built-in Notification
import type { Notification as AppNotification } from '../types/Notification';
import type { Unsubscribe } from 'firebase/firestore';

// Collection: notifications. Document IDs are generated by Firestore and copied into notifID.
const COLLECTION = 'notifications';

// ~~~~~~~~~~ CREATE ~~~~~~~~~~

// Returns the new notifID.
// Notifications about someone else's actions should be created by a Cloud Function, not the browser:
// once you write security rules, only the server should be allowed to create these.
export const createNotification = async (
  data: Omit<AppNotification, 'notifID' | 'notifTimestamp'>
): Promise<string> => {
  try {
    const ref = doc(collection(db, COLLECTION));
    await setDoc(ref, { ...data, notifID: ref.id, notifTimestamp: serverTimestamp() });
    return ref.id;
  } catch (error) {
    console.error('Error creating notification:', error);
    throw error;
  }
};

// ~~~~~~~~~~ READ ~~~~~~~~~~

// Get a user's notifications, newest first (the bell)
export const getNotificationsByUser = async (UID: string): Promise<AppNotification[]> => {
  try {
    const snap = await getDocs(query(collection(db, COLLECTION), where('UID', '==', UID)));
    return snap.docs
      .map(d => d.data() as AppNotification)
      .sort((a, b) => (b.notifTimestamp?.toMillis() ?? 0) - (a.notifTimestamp?.toMillis() ?? 0));
  } catch (error) {
    console.error(`Error getting notifications for user "${UID}":`, error);
    throw error;
  }
};

export const subscribeToNotificationsByUser = (
  UID: string,
  onNotifications: (notifications: AppNotification[]) => void,
  onError: (error: Error) => void,
): Unsubscribe => onSnapshot(
  query(collection(db, COLLECTION), where('UID', '==', UID)),
  snapshot => {
    const notifications = snapshot.docs
      .map(d => d.data() as AppNotification)
      .sort((a, b) => (b.notifTimestamp?.toMillis() ?? 0) - (a.notifTimestamp?.toMillis() ?? 0));
    onNotifications(notifications);
  },
  error => {
    console.error(`Error subscribing to notifications for user "${UID}":`, error);
    onError(error);
  },
);

export const markNotificationAsRead = async (notifID: string, UID: string): Promise<void> => {
  try {
    const notificationRef = doc(db, COLLECTION, notifID);
    await runTransaction(db, async transaction => {
      const snapshot = await transaction.get(notificationRef);
      if (!snapshot.exists()) throw new Error('This notification no longer exists.');
      if ((snapshot.data() as AppNotification).UID !== UID) {
        throw new Error('You are not allowed to update this notification.');
      }
      transaction.update(notificationRef, { isRead: true });
    });
  } catch (error) {
    console.error(`Error marking notification "${notifID}" as read:`, error);
    throw error;
  }
};

// ~~~~~~~~~~ DELETE ~~~~~~~~~~

export const deleteNotification = async (notifID: string): Promise<void> => {
  try {
    await deleteDoc(doc(db, COLLECTION, notifID));
  } catch (error) {
    console.error(`Error deleting notification "${notifID}":`, error);
    throw error;
  }
};